using System.Text.Json;
namespace P06;
public static class GroundTests {
    public static void Oracle(string input,string output){var w=new WorldSession();var rows=new List<object>();foreach(string line in File.ReadLines(input)){var p=line.Split('\t');w.Receive(Convert.FromHexString(p[1]),"");rows.Add(new{sample=p[0],plainHex=p[1],ground=w.Ground,objects=w.Objects});}Json.Save(output,new{status="pass",kind="original fixed JAR serializers with explicit synthetic input",rows});}
}
public sealed partial class LoginConnection {
