        Seed();string before=JsonSerializer.Serialize(c.World.Ground);foreach(int n in new[]{1,9,20,34}){try{Feed(packets["ground-8"][..n]);throw new Exception("truncated accepted");}catch(ProtocolException){}if(JsonSerializer.Serialize(c.World.Ground)!=before)throw new Exception("truncated mutation");}checks.Add("truncated packets fail atomically");
        foreach(uint n in new uint[]{0,2147483648,uint.MaxValue}){try{GroundRules.Request(112,32588,32930,1,n);throw new Exception("count width");}catch(ArgumentOutOfRangeException){}}checks.Add("positive signed Int32 request count only; 8-byte padded 16-byte request");
        foreach(bool pick in new[]{false,true})foreach(string change in new[]{"input","selection","remove","map","death","disconnect","count","movement","combat","item"}){
            Seed();int admitted=0;var gate=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);c.sendMovementGate=async(b,v,a)=>{await gate.Task;if(!v())return false;admitted++;a();return true;};var task=pick?c.PickupSelected(1):c.DropSelected(1);
            if(task.IsCompleted)throw new Exception("unexpected immediate gate refusal "+pick+" "+change);
            switch(change){case "input":c.CancelMovementInput();break;case "selection":if(pick){c.World.SelectGround(null);c.World.SelectGround(groundId);}else{c.World.SelectItem(null);c.World.SelectItem(100);}break;case "remove":if(pick)Feed(packets["remove"]);else Feed(LoginPackets.Pad([57,..BitConverter.GetBytes(100u)]));break;case "map":Feed(Convert.FromHexString("CE00000000000000"));break;case "death":Feed(LoginPackets.Pad([158,..BitConverter.GetBytes(c.World.Actor!.ObjectId),8]));break;case "disconnect":Seed();break;case "count":if(pick)Feed(packets["ground-2"]);else Feed(LoginPackets.Pad([24,..BitConverter.GetBytes(100u),36,50,51,0,..BitConverter.GetBytes(7u),0]));break;case "movement":c.nextMovementAt=Environment.TickCount64+1000;break;case "combat":c.nextCombatAt=Environment.TickCount64+1000;break;case "item":c.nextItemAt=Environment.TickCount64+1000;break;}
            gate.SetResult();if(await task||admitted!=0)throw new Exception("stale ground gate "+pick+" "+change);checks.Add((pick?"pickup":"drop")+" delayed gate cancels "+change);
        }
        foreach(bool pick in new[]{false,true}){Seed();int sent=0;c.sendMovementGate=(b,v,a)=>{if(!v())return Task.FromResult(false);a();sent++;return Task.FromResult(true);};if(!await(pick?c.PickupSelected(1):c.DropSelected(1))||await(pick?c.PickupSelected(1):c.DropSelected(1))||sent!=1||c.World.SelectedItem!.Count!=8||c.World.SelectedGround!.Count!=8)throw new Exception("one-shot no local mutation");c.Cancel();if(c.GroundBusy||c.World.Ground.Length!=0||c.World.SelectedGroundId!=null)throw new Exception("cancel ground state");}checks.Add("single send; rapid click refused; no predicted quantity; cancel resets pending guard and world");
