        if(!await c.PickupSelected(1)||delayedSent!=2)throw new Exception("explicit second action after original confirmation");Feed(LoginPackets.Pad([158,..BitConverter.GetBytes(origin.ObjectId),15]));if(c.World.Actor.Direction!=6)throw new Exception("second confirmed heading");checks.Add("same-generation late S158 action cannot bind to second target after 3s timeout; first association retained, second requires explicit action after confirmation");
        Json.Save(output,new{status="pass",kind="explicit synthetic delayed gates and original serializer inputs; not real gameplay proof",checks});
    }
